<style>.partner-create-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.partner-create-grid label{display:grid;gap:7px;font-size:.82rem;font-weight:600}.partner-create-grid input,.partner-create-grid select{width:100%;min-height:42px;padding:9px 11px;border:1px solid #d9d9d9;background:#fff;font:inherit}.partner-create-grid .third{grid-column:span 1}.partner-create-grid .full{grid-column:1/-1}.partner-create-help{padding:12px;background:#f8f7f4;color:#666;font-size:.82rem;line-height:1.5}@media(max-width:650px){.partner-create-grid{grid-template-columns:1fr}.partner-create-grid .full{grid-column:auto}}</style>
<div class="adm-form-section"><div class="adm-form-section-title"><i class="bi bi-building-add"></i> Partner institution and portal access</div><p class="muted">If this email already has a TCM One account, it will be linked to the partner without changing its role or password. For a new email, enter a temporary password for immediate login or leave it blank to send a password setup invitation. The partner can change the password in portal settings.</p><form method="post" action="<?= base_url('/admin/partners') ?>" class="partner-create-grid"><?= csrf_field() ?><label>Institution display name<input name="display_name" required></label><label>Legal organization name<input name="legal_name" required></label><label>Partner login email<input type="email" name="email" required><span class="muted">The partner uses this email at /partner/login.</span></label><label>Authorized representative<input name="contact_person"></label><label>Temporary password (optional)<input type="password" name="initial_password" minlength="10" autocomplete="new-password"><span class="muted">New accounts only; minimum 10 characters.</span></label><label>Confirm temporary password<input type="password" name="initial_password_confirm" minlength="10" autocomplete="new-password"></label><label>Phone<input name="phone"></label><label>Institution type<input name="institution_type"></label><label>City<input name="city"></label><label>Partnership model<select name="partnership_type"><option value="academic">Academic partnership (40/60 default)</option><option value="referral">Referral (15% default)</option><option value="custom">Custom agreement</option></select></label><label>Agreement starts<input type="date" name="effective_from"></label><label>Agreement ends<input type="date" name="effective_to"></label><label>Institute share % (custom)<input type="number" min="0" max="100" step=".01" name="institute_share"></label><label>TCM One share % (custom)<input type="number" min="0" max="100" step=".01" name=